INSERT INTO `ps_info_lang` (`id_info`, `id_shop`, `id_lang`, `text`) VALUES
(1, 1, 1, '<p style=\"text-align:center;\"><span style=\"font-family:\'PT Serif\', serif;font-size:13px;text-align:center;background-color:#ffffff;\">CZAS NA SPOTKANIE CZY CZAS NA RELAKS? CZAS NA HERBATĘ!</span><br style=\"font-family:\'PT Serif\', serif;font-size:13px;text-align:center;background-color:#ffffff;\" /><br style=\"font-family:\'PT Serif\', serif;font-size:13px;text-align:center;background-color:#ffffff;\" /><span style=\"font-family:\'PT Serif\', serif;font-size:13px;text-align:center;background-color:#ffffff;\">Czas na Herbatę to dużo więcej niż sklep z herbatami. To miejsce, w którym znajdziesz to, czego potrzebujesz, by wzbogacić każdy moment dnia. Czeka tu na Ciebie 620 rodzajów herbat (m.in. czarnych, białych, czerwonych, zielonych), różnorodne kawy z najdalszych zakątków świata, przepyszne czekolady, owocowe konfitury oraz naturalne, syropy i miody z polskich pasiek.</span></p>');
